'use client';

import React, { useEffect, useState, useCallback, useRef } from 'react';
import { usePathname } from 'next/navigation';
import GlobalSidebar, { SidebarMobileToggle } from './GlobalSidebar';
import { TabBar } from './TabBar';
import { arrayMove } from '@dnd-kit/sortable';
import { useSidebarState } from '@/hooks/useSidebarState';
import { useChamadosNotifications } from '@/hooks/useAdminChamadosNotifications';
import { useChecklistNotifications } from '@/hooks/useChecklistNotifications';
import NotificationToast from '@/components/chamados/NotificationToast';
import { ChamadoFinalizadoFeedbackDialog } from '@/components/chamados/ChamadoFinalizadoFeedbackDialog';
import { HoleriteNotificacaoGlobal } from '@/components/holerites/HoleriteNotificacaoGlobal';
import ChecklistNotificationToast from '@/components/Checklist/ChecklistNotificationToast';
import { MODULOS_REGISTRY } from '@/lib/modulos-registry';
import BibbleWeatherWidget from '@/components/BibbleChatHome/BibbleWeatherWidget';
import OnboardingModal from './OnboardingModal';
import { NotesGlobalTaskbar } from '@/components/Notas/NotesGlobalTaskbar';
import { NotaNotificacaoToast } from '@/components/Notas/NotaNotificacaoToast';
import { useNotasWorkspace } from '@/store/useNotasWorkspace';
import { useNotasNotifications } from '@/hooks/useNotasNotifications';
import { useNotasLembretesPendentes } from '@/hooks/useNotasLembretesPendentes';
import { useCalendarioAlphaNotifications } from '@/hooks/useCalendarioAlphaNotifications';
import { useCsNpsNotifications } from '@/hooks/useCsNpsNotifications';
import { CompromissoNotificacaoToast } from '@/components/CalendarioAlpha/CompromissoNotificacaoToast';
import { CsNpsPendenciasModal } from '@/components/cs-nps/CsNpsPendenciasModal';
import { CentralNotificacoesPainel } from './CentralNotificacoesPainel';
import { ChamadosOperacionaisPainel } from '@/components/chamados/ChamadosOperacionaisPainel';
import { isAdminRole, isSameRole } from '@/lib/roles';
import type { OnboardingVideo } from '@/lib/onboarding';
import type { LinkExternoVisivel } from '@/actions/LinksExternos';
import {
  AGENDA_ALPHA_LABEL,
  AGENDA_ALPHA_MENSAGEM,
  AGENDA_ALPHA_CONFIRMACAO_MENSAGEM,
  AGENDA_ALPHA_PRONTA_MENSAGEM,
  AGENDA_ALPHA_URL,
  type IntencaoAgendaAlpha,
} from '@/lib/google-calendar/navegacao';
import { signOut } from 'next-auth/react';
import { urlRepresentaLoginDoPainel } from '@/lib/auth/navegacao-sessao';
import {
  ensurePinnedHome,
  getTabsStorageKey,
  HOME_LABEL,
  HOME_TAB_ID,
  HOME_URL,
  parseStoredTabsState,
  type PainelTab,
} from '@/lib/painel-tabs';
import { getTema } from '@/lib/temas';
import { PainelEmbeddedReady } from './PainelEmbeddedReady';
import { PainelFrameFallback } from './PainelFrameFallback';
import {
  ALPHA_EMBED_READY,
  createPainelFrameId,
  createPainelFrameName,
  derivePainelEmbeddedUrl,
  getPainelFrameRuntimeState,
  isAlphaEmbedMessage,
  isPainelCanonicalUrl,
  PAINEL_EMBED_READY_TIMEOUT_MS,
  removePainelFrameState,
  retryPainelFrame,
  setPainelFrameStatus,
  type PainelFrameRuntimeByTab,
} from '@/lib/painel-embedded';

// ── Helpers ──────────────────────────────────────────────────────────────────

function getLabelForUrl(url: string): string {
  const mod = MODULOS_REGISTRY.find(m => url === m.href || url.startsWith(m.href + '/'));
  if (mod) return mod.label;
  const parts = url.split('/').filter(Boolean);
  return parts[parts.length - 1] || 'Página';
}

// ── Props ─────────────────────────────────────────────────────────────────────

interface PainelLayoutClientProps {
  children: React.ReactNode;
  permissoes: string[];
  role: string;
  userId: number;
  nome: string;
  imagemUrl?: string | null;
  temaName?: string;
  onboardingVisto?: boolean;
  onboardingVideo?: OnboardingVideo | null;
  linksExternos?: LinkExternoVisivel[];
}

// ── Component ─────────────────────────────────────────────────────────────────

export default function PainelLayoutClient({
  children,
  permissoes,
  role,
  userId,
  nome,
  imagemUrl,
  temaName,
  onboardingVisto = true,
  onboardingVideo = null,
  linksExternos = [],
}: PainelLayoutClientProps) {
  const { isCollapsed, isMobileOpen, toggleCollapse, toggleMobile, closeMobile } = useSidebarState();
  const pathname = usePathname();

  // Largura REAL da sidebar desktop, medida ao vivo (ResizeObserver) — a barra global de
  // notas encosta exatamente aqui, nunca num valor fixo assumido. Começa em 0 (mobile/sem
  // sidebar reservando espaço) até a primeira medição chegar.
  const [sidebarWidth, setSidebarWidth] = useState(0);
  const handleSidebarWidthChange = useCallback((width: number) => setSidebarWidth(width), []);

  // Onboarding obrigatório: mostra o vídeo até o usuário marcar como visto
  const [onboardingDone, setOnboardingDone] = useState(false);
  const showOnboarding = !onboardingVisto && !onboardingDone && !!onboardingVideo;

  // Sistema de Notas é uma camada global, mas ainda assim respeita a permissão do módulo 'notas'
  // (bypass padrão Admin/CEO/TI, mesmo critério usado em todo o restante do painel).
  const temAcessoNotas = isAdminRole(role) || permissoes.includes('notas');
  const temAcessoCalendarioAlpha = isAdminRole(role) || permissoes.includes('calendarioAlpha');
  // A barra de notas é `fixed bottom-0` no shell externo — os iframes de módulo não sabem que
  // ela existe (documentos isolados) e desenhariam conteúdo por baixo dela sem este respiro.
  const notasBarraVisivel = useNotasWorkspace((state) => state.isTaskbarVisible);
  const chamadosAccent = getTema(temaName).accent;

  useChamadosNotifications(role, userId);
  useNotasNotifications(temAcessoNotas ? userId : 0);
  useNotasLembretesPendentes(temAcessoNotas);
  useChecklistNotifications(role);
  useCalendarioAlphaNotifications(temAcessoCalendarioAlpha ? userId : 0);
  const { autorizado: podeReceberAlertasCs, reconciliar: reconciliarAlertasCs } = useCsNpsNotifications(role);

  // ── Embedded detection (running inside an iframe) ─────────────────────────
  // O primeiro render precisa ser idêntico no servidor e no navegador. Detectar `window`
  // no initializer fazia o SSR montar o shell completo e o iframe hidratar só `children`.
  const [isEmbedded, setIsEmbedded] = useState(false);
  useEffect(() => {
    let embedded = false;
    try { embedded = window !== window.top; } catch { embedded = true; }
    // eslint-disable-next-line react-hooks/set-state-in-effect -- detecção client-only após hidratação
    setIsEmbedded(embedded);
  }, []);
  const [tvMode, setTvMode] = useState(false);

  // Recebe postMessage dos iframes filhos (ex: Modo TV do Painel de Metas)
  useEffect(() => {
    const handler = (e: MessageEvent) => {
      if (e.origin !== window.location.origin) return;
      if (e.data?.type === 'ALPHA_TV_MODE') {
        setTvMode(e.data.active === true);
      }
    };
    window.addEventListener('message', handler);
    return () => window.removeEventListener('message', handler);
  }, []);

  // ── Tab state ─────────────────────────────────────────────────────────────
  const [tabs, setTabs] = useState<PainelTab[]>([]);
  const [activeId, setActiveId] = useState<string | null>(null);
  const [tabsHydrated, setTabsHydrated] = useState(false);
  const [frameRuntime, setFrameRuntime] = useState<PainelFrameRuntimeByTab>({});
  const encerrandoSessaoRef = useRef(false);
  const iframesRef = useRef(new Map<string, HTMLIFrameElement>());
  const lastOperationalUrlRef = useRef<string | null>(null);
  const intencaoAgendaPendenteRef = useRef<IntencaoAgendaAlpha | null>(null);
  const tabsStorageKey = getTabsStorageKey(userId);

  // Initialize: restore from localStorage or create from current URL
  useEffect(() => {
    /* eslint-disable react-hooks/set-state-in-effect -- inicialização das abas a partir do localStorage/URL */
    try {
      const saved = parseStoredTabsState(localStorage.getItem(tabsStorageKey));
      if (saved) {
        setTabs(saved.tabs);
        setActiveId(saved.activeId);
        setTabsHydrated(true);
        return;
      }
    } catch { /* ignore */ }

    // Fresh: home fixa + (se não estiver na home) a aba da página atual
    const onHome = pathname === HOME_URL || pathname === HOME_URL + '/';
    if (onHome) {
      setTabs([{ id: HOME_TAB_ID, url: HOME_URL, label: HOME_LABEL, pinned: true }]);
      setActiveId(HOME_TAB_ID);
    } else {
      const id = `tab-${Date.now()}`;
      setTabs([
        { id: HOME_TAB_ID, url: HOME_URL, label: HOME_LABEL, pinned: true },
        { id, url: pathname, label: getLabelForUrl(pathname) },
      ]);
      setActiveId(id);
    }
    setTabsHydrated(true);
    /* eslint-enable react-hooks/set-state-in-effect */
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Persist tabs whenever they change
  useEffect(() => {
    if (!tabsHydrated || tabs.length === 0 || !activeId) return;

    try {
      localStorage.setItem(tabsStorageKey, JSON.stringify({ tabs, activeId }));
    } catch { /* localStorage may be unavailable in restricted browsing modes */ }
  }, [tabs, activeId, tabsHydrated, tabsStorageKey]);

  // Publica ao IAlpha somente contexto same-origin e sem dados sensíveis. A
  // home continua sabendo qual foi o último módulo operacional visitado.
  useEffect(() => {
    const active = tabs.find(tab => tab.id === activeId);
    if (active && active.url !== HOME_URL) lastOperationalUrlRef.current = active.url;
    const home = tabs.find(tab => tab.url === HOME_URL);
    const frame = home ? iframesRef.current.get(home.id) : undefined;
    frame?.contentWindow?.postMessage({
      type: 'ALPHA_BIBBLE_CONTEXT',
      activeUrl: active?.url ?? HOME_URL,
      activeLabel: active?.label ?? HOME_LABEL,
      lastOperationalUrl: lastOperationalUrlRef.current,
      openModules: tabs.map(tab => ({ url: tab.url, label: tab.label })),
    }, window.location.origin);
  }, [activeId, tabs]);

  // ── Tab management ────────────────────────────────────────────────────────

  const openTab = useCallback((url: string, label: string) => {
    if (!isPainelCanonicalUrl(url)) return;
    setTabs(prev => {
      const existing = prev.find(t => t.url === url);
      if (existing) {
        setActiveId(existing.id);
        return prev;
      }
      const id = `tab-${Date.now()}`;
      setActiveId(id);
      return [...prev, { id, url, label }];
    });
  }, []);

  const entregarIntencaoAgenda = useCallback((intencao: IntencaoAgendaAlpha): boolean => {
    const abaAgenda = tabs.find(tab => tab.url === AGENDA_ALPHA_URL);
    const iframe = abaAgenda ? iframesRef.current.get(abaAgenda.id) : undefined;
    if (!iframe?.contentWindow) return false;
    iframe.contentWindow.postMessage(
      { type: AGENDA_ALPHA_MENSAGEM, intencao },
      window.location.origin,
    );
    return true;
  }, [tabs]);

  const abrirAgendaPorNotificacao = useCallback((intencao: IntencaoAgendaAlpha) => {
    intencaoAgendaPendenteRef.current = intencao;
    openTab(AGENDA_ALPHA_URL, AGENDA_ALPHA_LABEL);
    window.requestAnimationFrame(() => entregarIntencaoAgenda(intencao));
  }, [entregarIntencaoAgenda, openTab]);

  const abrirChamadosPorNotificacao = useCallback(() => {
    openTab('/PainelAlpha/Chamados', 'Chamados');
  }, [openTab]);

  const abrirNotasPorNotificacao = useCallback((noteId: string) => {
    openTab(`/PainelAlpha/Notas?id=${encodeURIComponent(noteId)}`, 'Bloco de notas ALpha');
  }, [openTab]);

  useEffect(() => {
    const pendente = intencaoAgendaPendenteRef.current;
    if (pendente) entregarIntencaoAgenda(pendente);
  }, [activeId, entregarIntencaoAgenda, tabs]);

  const closeTab = useCallback((id: string) => {
    setFrameRuntime(prev => removePainelFrameState(prev, id));
    setTabs(prev => {
      const target = prev.find(t => t.id === id);
      if (target?.pinned) return prev; // aba fixa (IAlpha) não fecha

      const idx = prev.findIndex(t => t.id === id);
      const filtered = prev.filter(t => t.id !== id);

      if (filtered.length === 0) {
        // Segurança: recria a home fixa
        setActiveId(HOME_TAB_ID);
        return [{ id: HOME_TAB_ID, url: HOME_URL, label: HOME_LABEL, pinned: true }];
      }

      setActiveId(curr => {
        if (curr !== id) return curr;
        return filtered[Math.max(0, idx - 1)].id;
      });
      return filtered;
    });
  }, []);

  const retryActiveFrame = useCallback(() => {
    if (!activeId) return;
    setFrameRuntime(prev => retryPainelFrame(prev, activeId));
  }, [activeId]);

  const activeFrameState = activeId
    ? getPainelFrameRuntimeState(frameRuntime, activeId)
    : null;

  useEffect(() => {
    if (!activeId || activeFrameState?.status !== 'loading') return;

    const attempt = activeFrameState.attempt;
    const timeout = window.setTimeout(() => {
      setFrameRuntime(prev => setPainelFrameStatus(prev, activeId, attempt, 'error'));
    }, PAINEL_EMBED_READY_TIMEOUT_MS);

    return () => window.clearTimeout(timeout);
  }, [activeFrameState?.attempt, activeFrameState?.status, activeId]);

  const reorderTabs = useCallback((draggedId: string, targetId: string) => {
    setTabs(prev => {
      const oldIndex = prev.findIndex(tab => tab.id === draggedId);
      const newIndex = prev.findIndex(tab => tab.id === targetId);
      const draggedTab = prev[oldIndex];
      const targetTab = prev[newIndex];

      if (
        oldIndex < 0 ||
        newIndex < 0 ||
        oldIndex === newIndex ||
        draggedTab?.pinned ||
        targetTab?.pinned
      ) {
        return prev;
      }

      return ensurePinnedHome(arrayMove(prev, oldIndex, newIndex));
    });
  }, []);

  // Handshake de hidratação dos iframes. O listener é estável e consulta o Map de refs
  // ao vivo, evitando perder a mensagem de um módulo que carregue entre dois renders.
  useEffect(() => {
    const handler = (event: MessageEvent) => {
      if (event.origin !== window.location.origin || !isAlphaEmbedMessage(event.data)) return;
      const message = event.data;

      const sourceEntry = Array.from(iframesRef.current.entries()).find(
        ([, iframe]) => iframe.contentWindow === event.source,
      );
      if (!sourceEntry) return;

      const [sourceTabId] = sourceEntry;
      setFrameRuntime(prev => {
        const current = getPainelFrameRuntimeState(prev, sourceTabId);
        const expectedFrameId = createPainelFrameId(sourceTabId, current.attempt);
        if (message.frameId !== expectedFrameId) return prev;

        const status = message.type === ALPHA_EMBED_READY ? 'ready' : 'loading';
        return setPainelFrameStatus(prev, sourceTabId, current.attempt, status);
      });
    };

    window.addEventListener('message', handler);
    return () => window.removeEventListener('message', handler);
  }, []);

  // Recebe ALPHA_OPEN_TAB dos iframes filhos (ex: PainelAlpha abrindo módulo em nova aba)
  useEffect(() => {
    const handler = (e: MessageEvent) => {
      if (e.origin !== window.location.origin) return;
      if (e.data?.type === 'ALPHA_OPEN_TAB' && e.data.url) {
        openTab(e.data.url, e.data.label || getLabelForUrl(e.data.url));
      }
      const abaAgenda = tabs.find(tab => tab.url === AGENDA_ALPHA_URL);
      const origemEhAgenda = abaAgenda
        ? iframesRef.current.get(abaAgenda.id)?.contentWindow === e.source
        : false;
      if (origemEhAgenda && e.data?.type === AGENDA_ALPHA_PRONTA_MENSAGEM) {
        const pendente = intencaoAgendaPendenteRef.current;
        if (pendente) entregarIntencaoAgenda(pendente);
      }
      if (origemEhAgenda && e.data?.type === AGENDA_ALPHA_CONFIRMACAO_MENSAGEM) {
        intencaoAgendaPendenteRef.current = null;
      }
    };
    window.addEventListener('message', handler);
    return () => window.removeEventListener('message', handler);
  }, [entregarIntencaoAgenda, openTab, tabs]);

  // ── Embedded: render children only, no sidebar/tabs ──────────────────────

  if (isEmbedded || role === 'TV') {
    return (
      <>
        {children}
        {isEmbedded && <PainelEmbeddedReady />}
      </>
    );
  }

  // ── Derived values ────────────────────────────────────────────────────────

  const activeTab = tabs.find(t => t.id === activeId);
  const activeUrl = activeTab?.url ?? pathname;
  const openUrls = tabs.map(t => t.url);

  const sidebarOffset = isCollapsed ? 'lg:pl-[72px]' : 'lg:pl-[260px]';

  return (
    <>
      <NotificationToast onAbrirChamados={abrirChamadosPorNotificacao} />
      <ChamadoFinalizadoFeedbackDialog accent={chamadosAccent} />
      <ChecklistNotificationToast />
      <HoleriteNotificacaoGlobal authenticated />
      <NotaNotificacaoToast onAbrirNota={abrirNotasPorNotificacao} />
      {temAcessoCalendarioAlpha && <CompromissoNotificacaoToast onAbrirAgenda={abrirAgendaPorNotificacao} />}
      {podeReceberAlertasCs && <CsNpsPendenciasModal onReconciliar={reconciliarAlertasCs} />}

      {!tvMode && (
        <GlobalSidebar
          permissoes={permissoes}
          openUrls={openUrls}
          role={role}
          nome={nome}
          imagemUrl={imagemUrl}
          isCollapsed={isCollapsed}
          isMobileOpen={isMobileOpen}
          onToggleCollapse={toggleCollapse}
          onCloseMobile={closeMobile}
          onOpenTab={openTab}
          activeUrl={activeUrl}
          temaName={temaName}
          onWidthChange={handleSidebarWidthChange}
          linksExternos={linksExternos}
        />
      )}

      {/* Mobile hamburger */}
      {!tvMode && (
        <div className="lg:hidden fixed top-4 left-4 z-[55]">
          <SidebarMobileToggle onClick={toggleMobile} />
        </div>
      )}

      {/* Main content area */}
      <div className={`transition-all duration-300 ease-in-out ${tvMode ? '' : sidebarOffset} flex flex-col h-dvh`}>

        {/* Tab bar + widget de clima */}
        {!tvMode && (
          <div className="relative flex items-center shrink-0 h-10 bg-[#030813] border-b border-white/[0.06]">
            <div className="flex-1 min-w-0 overflow-hidden">
              <TabBar
                tabs={tabs}
                activeId={activeId}
                onActivate={setActiveId}
                onClose={closeTab}
                onReorder={reorderTabs}
              />
            </div>
            <div className="shrink-0 flex items-center gap-2 pr-3">
              <CentralNotificacoesPainel
                onAbrirAgenda={abrirAgendaPorNotificacao}
                onAbrirModulo={openTab}
                onAbrirNota={abrirNotasPorNotificacao}
              />
              {isSameRole(role, 'TI') && (
                <ChamadosOperacionaisPainel
                  usuarioAtualId={userId}
                  onAbrirModulo={() => openTab('/PainelAlpha/Chamados', 'Chamados')}
                />
              )}
              <BibbleWeatherWidget />
            </div>
          </div>
        )}

        {/* Page content — reserva o espaço da barra de notas (fixed, fora dos iframes) para
            que nenhum módulo desenhe conteúdo por baixo dela (ex: rodapé da sidebar do Bibble
            na Home). A barra só ocupa a largura toda no desktop (lg+) — no mobile/tablet ela
            vira um botão flutuante (FAB) que não precisa de respiro reservado no conteúdo. */}
        <div
          className={`flex-1 overflow-hidden relative transition-[padding] duration-200 ease-in-out ${
            !tvMode && temAcessoNotas && notasBarraVisivel ? 'lg:pb-10' : ''
          }`}
        >

          {activeTab && activeFrameState?.status !== 'ready' && (
            <PainelFrameFallback
              isError={activeFrameState?.status === 'error'}
              moduleLabel={activeTab.label}
              onRetry={retryActiveFrame}
            />
          )}

          {/* One iframe per tab — inactive ones are hidden but STAY MOUNTED */}
          {tabs.map(tab => {
            const isActive = tab.id === activeId;
            const runtime = getPainelFrameRuntimeState(frameRuntime, tab.id);
            const frameId = createPainelFrameId(tab.id, runtime.attempt);
            const visible = isActive && runtime.status === 'ready';

            return (
              <iframe
                key={`${tab.id}:${runtime.attempt}`}
                ref={(elemento) => {
                  if (elemento) iframesRef.current.set(tab.id, elemento);
                  else iframesRef.current.delete(tab.id);
                }}
                src={derivePainelEmbeddedUrl(tab.url, frameId)}
                name={createPainelFrameName(frameId)}
                title={tab.label}
                allow="autoplay; fullscreen"
                allowFullScreen
                className={`absolute inset-0 h-full w-full border-none ${
                  !isActive
                    ? 'hidden'
                    : visible
                      ? 'visible pointer-events-auto'
                      : 'invisible pointer-events-none'
                }`}
                onLoad={(event) => {
                  let childConfirmedReady = false;
                  try {
                    childConfirmedReady =
                      event.currentTarget.contentDocument?.documentElement.dataset.alphaEmbeddedReady === frameId;
                  } catch {
                    // Navegação cross-origin nunca pode liberar uma aba interna.
                  }
                  setFrameRuntime(prev =>
                    setPainelFrameStatus(
                      prev,
                      tab.id,
                      runtime.attempt,
                      childConfirmedReady ? 'ready' : 'loading',
                    ),
                  );

                  const intencaoPendente = intencaoAgendaPendenteRef.current;
                  if (tab.url === AGENDA_ALPHA_URL && intencaoPendente) {
                    event.currentTarget.contentWindow?.postMessage(
                      { type: AGENDA_ALPHA_MENSAGEM, intencao: intencaoPendente },
                      window.location.origin,
                    );
                  }
                  if (tab.url === HOME_URL) {
                    const active = tabs.find(item => item.id === activeId);
                    event.currentTarget.contentWindow?.postMessage({
                      type: 'ALPHA_BIBBLE_CONTEXT', activeUrl: active?.url ?? HOME_URL,
                      activeLabel: active?.label ?? HOME_LABEL,
                      lastOperationalUrl: lastOperationalUrlRef.current,
                      openModules: tabs.map(item => ({ url: item.url, label: item.label })),
                    }, window.location.origin);
                  }
                  try {
                    const href = event.currentTarget.contentWindow?.location.href;
                    if (
                      href &&
                      urlRepresentaLoginDoPainel(href, window.location.origin) &&
                      !encerrandoSessaoRef.current
                    ) {
                      encerrandoSessaoRef.current = true;
                      void signOut({ redirectTo: '/' });
                    }
                  } catch {
                    // Um iframe cross-origin não participa da autenticação do painel.
                  }
                }}
              />
            );
          })}

          {/* Loading state during initialization */}
          {tabs.length === 0 && (
            <div className="flex items-center justify-center h-full">
              <span className="text-2xl font-black italic text-slate-800 animate-pulse">α</span>
            </div>
          )}

          {/* Onboarding — só na aba inicial (IAlpha); outros módulos ficam livres */}
          {showOnboarding && onboardingVideo && activeUrl === HOME_URL && (
            <OnboardingModal video={onboardingVideo} onDone={() => setOnboardingDone(true)} />
          )}
        </div>
      </div>

      {/* Camada global de notas — fora do container de iframes, sobreposta ao rodapé de qualquer módulo aberto.
          Encosta exatamente onde a sidebar termina de verdade (sidebarWidth medido ao vivo via
          ResizeObserver em GlobalSidebar) — nunca um valor fixo assumido, então nunca sobrepõe a
          sidebar mesmo que a largura real dela mude ou dessincronize do CSS esperado. No mobile/
          tablet (< lg, sidebar em modo "gaveta") sidebarWidth fica 0 e a barra ocupa a largura toda. */}
      {!tvMode && temAcessoNotas && (
        <NotesGlobalTaskbar
          userId={userId}
          sidebarWidth={sidebarWidth}
          onOpenCentral={() => openTab('/PainelAlpha/Notas', getLabelForUrl('/PainelAlpha/Notas'))}
        />
      )}
    </>
  );
}
